-- Business-line units (Zen 360 Phase 0 Wave 6, PR 1; SPINE-CONTRACT s.1.0 and
-- Opus decision 12). A unit is a dated row beside OrgUnit, which is not changed.
--
-- The name sorts after 20261010235900_tenant_rls, so that migration does not
-- cover this table on a fresh database. Section 8 states its policies here, so
-- the migration is correct on its own, including where tenant_rls has run.
-- The CreateTable and indexes are generated by migrate diff; the rest is
-- hand-written and tested in src/tests/units.test.ts.

-- CreateTable
CREATE TABLE "units" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'active',
    "lineId" TEXT,
    "parentUnitId" TEXT,
    "effectiveFrom" DATE NOT NULL,
    "effectiveTo" DATE,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "units_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "units_tenantId_code_idx" ON "units"("tenantId", "code");

-- CreateIndex
CREATE INDEX "units_tenantId_lineId_idx" ON "units"("tenantId", "lineId");

-- CreateIndex
CREATE INDEX "units_tenantId_parentUnitId_idx" ON "units"("tenantId", "parentUnitId");

-- CreateIndex
CREATE UNIQUE INDEX "units_tenantId_id_key" ON "units"("tenantId", "id");

-- AddForeignKey
ALTER TABLE "units" ADD CONSTRAINT "units_tenantId_lineId_fkey" FOREIGN KEY ("tenantId", "lineId") REFERENCES "business_lines"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "units" ADD CONSTRAINT "units_tenantId_parentUnitId_fkey" FOREIGN KEY ("tenantId", "parentUnitId") REFERENCES "units"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ---------------------------------------------------------------------------
-- Hand-written from here down. Prisma cannot model these, and each one must
-- hold for every writer, not only for the domain functions that check it.
-- ---------------------------------------------------------------------------

-- 1. A row's identity and placement are fixed when it is opened. A move closes
--    the row (effectiveTo and status change, and nothing else) and opens a new
--    one with the new line. Editing lineId in place would rewrite which line
--    the unit was in on every past day, so the database refuses it.
CREATE OR REPLACE FUNCTION units_guard_keys() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."id" IS DISTINCT FROM OLD."id"
     OR NEW."tenantId" IS DISTINCT FROM OLD."tenantId"
     OR NEW."code" IS DISTINCT FROM OLD."code"
     OR NEW."lineId" IS DISTINCT FROM OLD."lineId"
     OR NEW."parentUnitId" IS DISTINCT FROM OLD."parentUnitId"
     OR NEW."effectiveFrom" IS DISTINCT FROM OLD."effectiveFrom" THEN
    RAISE EXCEPTION 'units: id, tenantId, code, lineId, parentUnitId and effectiveFrom are immutable; a move closes this row and opens another'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "units_guard_keys"
  BEFORE UPDATE ON "units"
  FOR EACH ROW EXECUTE FUNCTION units_guard_keys();

-- 2. A row ends after it starts. A NULL end is open-ended.
ALTER TABLE "units"
  ADD CONSTRAINT "units_dates_ordered"
  CHECK ("effectiveTo" IS NULL OR "effectiveTo" > "effectiveFrom");

-- 3. The status is one of two values, and 'closed' exactly when an end is set.
--    A dated close is recorded with its end; there is no closed row without one.
ALTER TABLE "units"
  ADD CONSTRAINT "units_status_values"
  CHECK ("status" IN ('active', 'closed'));

ALTER TABLE "units"
  ADD CONSTRAINT "units_status_end_agree"
  CHECK (("status" = 'closed') = ("effectiveTo" IS NOT NULL));

-- 4. Rows of one code do not overlap: a unit is in one place on any day. The
--    range is half-open, so a row ending on a day and its successor starting on
--    that day are adjacent and both allowed. This replaces a plain UNIQUE on
--    (tenantId, code), which would refuse every move, since a move keeps the code.
CREATE EXTENSION IF NOT EXISTS btree_gist;

ALTER TABLE "units"
  ADD CONSTRAINT "units_code_no_overlap"
  EXCLUDE USING gist (
    "tenantId" WITH =,
    "code" WITH =,
    daterange("effectiveFrom", "effectiveTo", '[)') WITH &&
  );

-- 5. The application role may read and write a unit, and never delete one.
--    tenant_rls grants every privilege on the tables it discovers; this table
--    sorts after it, so the grant and the revoke are explicit here.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kaizen_app') THEN
    GRANT SELECT, INSERT, UPDATE ON "units" TO "kaizen_app";
    REVOKE DELETE ON "units" FROM "kaizen_app";
  END IF;
END
$$;

-- 6. Row-level security. Enabled, forced and policed here, because this
--    migration sorts after tenant_rls (rlsMigrationOrder.test.ts checks it).
ALTER TABLE "units" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "units" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "units";
CREATE POLICY "tenant_isolation" ON "units"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));
